mapper.update:
UPDATE ai_conversation
SET deleted_at = UTC_TIMESTAMP()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM ai_conversation
WHERE id = #{id}
  AND user_id = #{userId}

WITH first_user AS ( SELECT m.conversation_id AS conversation_id, m.content AS content, ROW_NUMBER() OVER (PARTITION BY m.conversation_id ORDER BY m.id ASC) AS rn FROM ai_message m WHERE m.role = 'user' ), ref_agg AS ( SELECT m.conversation_id AS conversation_id, COUNT(jt.law_item_id) AS ref_count FROM ai_message m, JSON_TABLE(m.refs, '$[*]' COLUMNS (law_item_id BIGINT PATH '$.lawItemId')) AS jt WHERE m.role = 'assistant' AND m.refs IS NOT NULL GROUP BY m.conversation_id ) SELECT c.id AS id, c.user_id AS userId, COALESCE(NULLIF(u.nickname, ''), u.phone) AS userName, c.title AS title, c.lang AS lang, c.created_at AS createdAt, c.updated_at AS updatedAt, c.deleted_at AS deletedAt, LEFT(f.content, 30) AS questionSummary, COALESCE(r.ref_count, 0) AS refCount, COUNT(*) OVER () AS total FROM ai_conversation c LEFT JOIN app_user u ON u.id = c.user_id LEFT JOIN first_user f ON f.conversation_id = c.id AND f.rn = 1 LEFT JOIN ref_agg r ON r.conversation_id = c.id
AND c.user_id = #{userId}
AND c.created_at >= #{beginTime}
AND c.created_at <= #{endTime}
ORDER BY c.updated_at DESC, c.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COALESCE(NULLIF(u.nickname, ''), u.phone)
FROM app_user u
WHERE u.id = #{userId}
